const lookup = (table, code) => (code == null ? null : table[String(code)] ?? null)

export function ccaaName(code) {
	return lookup(CCAA_PT, code)
}

export function provinceName(code) {
	return lookup(PROVINCE_PT, code)
}

// Display name of a zone (a GeoJSON feature or its properties): AEMET's
// Spanish name, with the coastal prefix "Costa - " typeset as "Costa — ".
export function zoneLabel(feature) {
	const name = (feature?.properties ?? feature)?.name ?? ''
	return name.replace(/^Costa - /, 'Costa — ')
}
